%% guide - the code of guides/sv_compare/README.md: three models of y_t, a constant variance,
% stochastic volatility (SV) and SV with Student-t errors (SV-t), compared by their marginal
% likelihoods on two data sets: the data of guides/sv_states, generated by SV, and the data of
% guides/sv_t, generated by SV-t. ssm.intlike_sv and ssm.intlike_sv_t integrate the
% log-volatilities out, the Gibbs samplers of guides/sv_gibbs and guides/sv_t draw the
% parameters, and importance sampling with the cross-entropy importance density estimates the
% marginal likelihoods. Section 2 computes the Bayes factor of SV-t against SV under other
% priors of nu from the same draws. Section 3 changes the prior of mu_h. The sections called
% "the code to adapt" are all a comparison needs. The checks compute the marginal likelihood
% of the constant variance by quadrature, the integrated likelihood of the first 50
% observations by importance sampling from the prior of h, the estimates under another seed
% and with more draws of h, and one marginal likelihood of section 2 from a new run. Saves
% fig_prior.png next to this file.

here = fileparts(mfilename('fullpath'));
run(fullfile(fileparts(fileparts(here)), 'setup.m'));
t_all = tic;

%% the data of guides/sv_states and of guides/sv_t, in percent
rng(42, 'twister');
T = 1000; mu_true = .1; muh_true = 0; phi_true = .97; sig2h_true = .04; nu_true = 5;
h_true = zeros(T,1);
h_true(1) = muh_true + sqrt(sig2h_true/(1 - phi_true^2))*randn;
for t = 2:T
    h_true(t) = muh_true + phi_true*(h_true(t-1) - muh_true) + sqrt(sig2h_true)*randn;
end
epsn = randn(T,1);
lam_true = 1./gamrnd(nu_true/2, 2/nu_true, T, 1);    % lambda_t ~ IG(nu/2, nu/2)
Y = {mu_true + exp(h_true/2).*epsn, ...               % SV: the data of guides/sv_states
     mu_true + sqrt(lam_true).*exp(h_true/2).*epsn};  % SV-t: the data of guides/sv_t
dnames = {'SV data', 'SV-t data'};
mnames = {'constant variance', 'SV', 'SV-t'};
rng(2, 'twister');

%% 1. the three models and their marginal likelihoods: the code to adapt
pr = struct('mu0', 0, 'Vmu', 10, 'muh0', 1, 'Vmuh', 10, 'phi0', .97, 'Vphi', .1^2, ...
    'nuh', 5, 'Sh', .16, 'nuub', 100);                 % the priors of guides/sv_gibbs and guides/sv_t
lnorm = @(x, m, V) -.5*log(2*pi*V) - .5*(x - m).^2/V;  % log N(x; m, V)
lig = @(x, nu, S) nu*log(S) - gammaln(nu) - (nu + 1)*log(x) - S./x;  % log IG(x; nu, S)
cphi = log(normcdf((1 - pr.phi0)/sqrt(pr.Vphi)) - normcdf((-1 - pr.phi0)/sqrt(pr.Vphi)));
lprior = @(mu, muh, phi, sig2h) lnorm(mu, pr.mu0, pr.Vmu) + lnorm(muh, pr.muh0, pr.Vmuh) ...
    + lnorm(phi, pr.phi0, pr.Vphi) - cphi + lig(sig2h, pr.nuh, pr.Sh);  % phi ~ TN on (-1, 1)
nuof = @(z) 2 + (pr.nuub - 2)./(1 + exp(-z));          % nu = 2 + (nuub - 2)/(1 + e^{-z})
ljnu = @(nu) log((nu - 2).*(pr.nuub - nu)/(pr.nuub - 2));  % log dnu/dz
nsim = 5000; burnin = 500; R = 5000; Mh = 50;
lml = zeros(3, 2); nse = lml; lbm = lml; ess = lml; post = cell(3, 2); hbar = cell(3, 2);
lml_q = zeros(1, 2); lratio = lml_q;
for d = 1:2
    y = Y{d};
    % constant variance: y_t ~ N(mu, e^{mu_h}), z = (mu, mu_h); exact draws and quadrature
    [lml_q(d), post{1,d}, lratio(d)] = cv_posterior(y, pr, nsim);
    lp_cv = @(z) sum(lnorm(y, z(1), exp(z(2)))) + lnorm(z(1), pr.mu0, pr.Vmu) ...
        + lnorm(z(2), pr.muh0, pr.Vmuh);
    [lml(1,d), nse(1,d), lbm(1,d), ess(1,d)] = is_logml(lp_cv, post{1,d}, R);

    % SV: z = (mu, mu_h, atanh(phi), log sigma_h^2); the draws of guides/sv_gibbs
    [th, hbar{2,d}] = sv_gibbs(y, nsim, burnin, pr);
    post{2,d} = [th(:,1:2) atanh(th(:,3)) log(th(:,4))];
    hb = hbar{2,d};
    lp_sv = @(z) ssm.intlike_sv((y - z(1)).^2, z(2), tanh(z(3)), exp(z(4)), hb, Mh) ...
        + lprior(z(1), z(2), tanh(z(3)), exp(z(4))) ...
        + log(1 - tanh(z(3))^2) + z(4);                % log Jacobian of (phi, sigma_h^2)
    [lml(2,d), nse(2,d), lbm(2,d), ess(2,d)] = is_logml(lp_sv, post{2,d}, R);

    % SV-t: z adds log((nu - 2)/(nuub - nu)); the draws of guides/sv_t
    [th, hbar{3,d}] = svt_gibbs(y, nsim, burnin, pr);
    post{3,d} = [th(:,1:2) atanh(th(:,3)) log(th(:,4)) log((th(:,5) - 2)./(pr.nuub - th(:,5)))];
    hb = hbar{3,d};
    lp_svt = @(z) ssm.intlike_sv_t((y - z(1)).^2, z(2), tanh(z(3)), exp(z(4)), nuof(z(5)), hb, Mh) ...
        + lprior(z(1), z(2), tanh(z(3)), exp(z(4))) - log(pr.nuub - 2) ...  % nu ~ U(2, nuub)
        + log(1 - tanh(z(3))^2) + z(4) + ljnu(nuof(z(5)));
    [lml(3,d), nse(3,d), lbm(3,d), ess(3,d)] = is_logml(lp_svt, post{3,d}, R);
end

%% 1. the results and the checks
fprintf('\nlog marginal likelihoods (numerical standard errors), R = %d, %d draws of h per call\n', R, Mh);
fprintf('%-18s %22s %22s\n', '', dnames{:});
for m = 1:3
    fprintf('%-18s %13.2f (%.3f) %13.2f (%.3f)\n', mnames{m}, lml(m,1), nse(m,1), lml(m,2), nse(m,2));
end
pairs = [2 1; 3 2; 3 1];
fprintf('\nlog Bayes factors (numerical standard errors)\n');
for p = 1:3
    a = pairs(p,1); b = pairs(p,2);
    fprintf('%-6s against %-18s %10.2f (%.3f) %10.2f (%.3f)\n', mnames{a}, mnames{b}, ...
        lml(a,1) - lml(b,1), hypot(nse(a,1), nse(b,1)), lml(a,2) - lml(b,2), hypot(nse(a,2), nse(b,2)));
end
fprintf('\nposterior means: SV data, SV-t: nu %.1f; SV-t data, SV-t: nu %.2f\n', ...
    mean(nuof(post{3,1}(:,5))), mean(nuof(post{3,2}(:,5))));
fprintf('effective sample size of the importance weights, share of R:\n');
for m = 1:3, fprintf('  %-18s %.2f %.2f\n', mnames{m}, ess(m,:)); end
fprintf('the mean of the 20 batch estimates minus the estimate from all R draws: %s\n', ...
    mat2str(round(lbm - lml, 4)));

% the constant variance: quadrature against importance sampling
for d = 1:2
    fprintf(['constant variance, %s: trapezoid rule %.4f, log of the ratio of the two integrals %.1e, ' ...
        'importance sampling %.4f, %.1f numerical standard errors apart\n'], dnames{d}, ...
        lml_q(d), lratio(d), lml(1,d), (lml(1,d) - lml_q(d))/nse(1,d));
end

% the noise of log p(y | theta) with 50 draws of h, at the posterior means of SV: the nse of
% one call, and the spread of 20 calls
for d = 1:2
    z = mean(post{2,d}); llr = zeros(20, 1); nsr = llr;
    for r = 1:20
        [llr(r), nsr(r)] = ssm.intlike_sv((Y{d} - z(1)).^2, z(2), tanh(z(3)), exp(z(4)), hbar{2,d}, Mh);
    end
    fprintf(['SV on the %s: log p(y | theta) has nse %.3f from one call (median over 20 calls %.3f); ' ...
        'its standard deviation over the 20 calls is %.3f\n'], dnames{d}, nsr(1), median(nsr), std(llr));
end

% the integrated likelihood of the first T0 = 50 observations, at the posterior means:
% ssm.intlike_sv(_t) against importance sampling from the prior of h
T0 = 50;
for c = 1:2
    d = c; m = c + 1; y = Y{d}(1:T0);  % SV on the SV data, SV-t on the SV-t data
    z = mean(post{m,d});
    nu = Inf; if m == 3, nu = nuof(z(5)); end
    s2 = (y - z(1)).^2;
    if m == 2
        [lq, nq] = ssm.intlike_sv(s2, z(2), tanh(z(3)), exp(z(4)), hbar{m,d}(1:T0), 1e5);
    else
        [lq, nq] = ssm.intlike_sv_t(s2, z(2), tanh(z(3)), exp(z(4)), nu, hbar{m,d}(1:T0), 1e5);
    end
    [lpi, sepi] = prior_is(s2, z(2), tanh(z(3)), exp(z(4)), nu, 1e5, 20);
    fprintf(['%s on the %s, T0 = %d: intlike %.4f (nse %.4f); importance sampling from the prior ' ...
        'of h %.4f (standard error %.4f); %.1f joint standard errors apart\n'], mnames{m}, dnames{d}, ...
        T0, lq, nq, lpi, sepi, (lq - lpi)/hypot(nq, sepi));
end

% another seed, and more draws of h per call
lml_s = zeros(2, 2); nse_s = lml_s; lml_m = lml_s; nse_m = lml_s;
rng(3, 'twister');
for d = 1:2
    y = Y{d};
    for m = 2:3
        for k = 1:2
            if k == 1, Mk = Mh; Rk = R; else, Mk = 4*Mh; Rk = R/2; end
            hb = hbar{m,d};
            if m == 2
                lp = @(z) ssm.intlike_sv((y - z(1)).^2, z(2), tanh(z(3)), exp(z(4)), hb, Mk) ...
                    + lprior(z(1), z(2), tanh(z(3)), exp(z(4))) + log(1 - tanh(z(3))^2) + z(4);
            else
                lp = @(z) ssm.intlike_sv_t((y - z(1)).^2, z(2), tanh(z(3)), exp(z(4)), nuof(z(5)), hb, Mk) ...
                    + lprior(z(1), z(2), tanh(z(3)), exp(z(4))) - log(pr.nuub - 2) ...
                    + log(1 - tanh(z(3))^2) + z(4) + ljnu(nuof(z(5)));
            end
            if k == 1
                [lml_s(m-1,d), nse_s(m-1,d)] = is_logml(lp, post{m,d}, Rk);
            else
                [lml_m(m-1,d), nse_m(m-1,d)] = is_logml(lp, post{m,d}, Rk);
            end
        end
    end
end
fprintf('\nseed 3 and %d draws of h, R = %d; %d draws of h, R = %d:\n', Mh, R, 4*Mh, R/2);
for d = 1:2
    for m = 2:3
        fprintf(['  %-5s %-9s main %.2f (%.3f), seed 3 %.2f (%.3f), %d draws of h %.2f (%.3f); ' ...
            'largest gap %.1f joint standard errors\n'], mnames{m}, dnames{d}, lml(m,d), nse(m,d), ...
            lml_s(m-1,d), nse_s(m-1,d), 4*Mh, lml_m(m-1,d), nse_m(m-1,d), ...
            max(abs([lml_s(m-1,d) - lml(m,d), lml_m(m-1,d) - lml(m,d)]./ ...
            [hypot(nse_s(m-1,d), nse(m,d)), hypot(nse_m(m-1,d), nse(m,d))])));
    end
end

%% 2. the prior of nu: the log Bayes factor of SV-t against SV, from the same draws
% p_b(y) = p(y) * E[p_b(nu)/p(nu) | y] for nu ~ U(2, b), b <= nuub, under which
% p_b(nu)/p(nu) = (nuub - 2)/(b - 2) for nu < b and 0 otherwise
bs = [5 10 20 30 50 100];
fprintf(['\nlog Bayes factor of SV-t against SV for nu ~ U(2, b): value (Monte Carlo standard ' ...
    'error of log P), P = posterior probability of nu < b\n']);
fprintf('%6s %34s %34s\n', 'b', dnames{:});
lbf_b = zeros(numel(bs), 2); pb = lbf_b; sep = lbf_b;
for i = 1:numel(bs)
    fprintf('%6d', bs(i));
    for d = 1:2
        ind = double(nuof(post{3,d}(:,5)) < bs(i));
        pb(i,d) = mean(ind);
        sep(i,d) = ssm.mcse(ind, 200)/pb(i,d);  % the standard error of log P, by the delta method
        lbf_b(i,d) = lml(3,d) - lml(2,d) + log((pr.nuub - 2)/(bs(i) - 2)) + log(pb(i,d));
        if pb(i,d) > 0
            fprintf(' %12.2f (%.2f), P = %.3f', lbf_b(i,d), sep(i,d), pb(i,d));
        else
            fprintf(' %34s', 'no draw of nu below b');
        end
    end
    fprintf('\n');
end

%% 2. the checks: the marginal likelihood of SV-t on the SV data with nu ~ U(2, 30), from a new run
rng(4, 'twister');
pr30 = pr; pr30.nuub = 30; y = Y{1};
[th, hb] = svt_gibbs(y, nsim, burnin, pr30);
z30 = [th(:,1:2) atanh(th(:,3)) log(th(:,4)) log((th(:,5) - 2)./(30 - th(:,5)))];
nuof30 = @(z) 2 + 28./(1 + exp(-z));
lp30 = @(z) ssm.intlike_sv_t((y - z(1)).^2, z(2), tanh(z(3)), exp(z(4)), nuof30(z(5)), hb, Mh) ...
    + lprior(z(1), z(2), tanh(z(3)), exp(z(4))) - log(28) ...
    + log(1 - tanh(z(3))^2) + z(4) + log((nuof30(z(5)) - 2).*(30 - nuof30(z(5)))/28);
[l30, n30] = is_logml(lp30, z30, R);
fprintf(['SV-t on the SV data with nu ~ U(2, 30): new run %.2f (%.3f); from the draws of ' ...
    'section 1 %.2f (%.2f)\n'], l30, n30, lml(3,1) + log(98/28) + log(pb(bs == 30, 1)), sep(bs == 30, 1));

%% the figure: the log Bayes factor of SV-t against SV against the upper bound of the prior of nu
bgrid = linspace(4, 100, 193);
fig = figure('Visible', 'off', 'Units', 'centimeters', 'Position', [2 2 16 10]); hold on
st = {'-', '--'}; hl = gobjects(1, 2);
for d = [2 1]
    p = arrayfun(@(b) mean(nuof(post{3,d}(:,5)) < b), bgrid);
    ok = p*nsim >= 50;                                 % at least 50 draws of nu below b
    v = lml(3,d) - lml(2,d) + log((pr.nuub - 2)./(bgrid - 2)) + log(p);
    hl(d) = plot(bgrid(ok), v(ok), st{d}, 'Color', 'k', 'LineWidth', 1.2);
end
yline(0, ':');
hold off; box off
xlabel('upper bound b of the prior \nu \sim U(2, b)'); ylabel('log Bayes factor');
legend(hl, {'SV data', 'SV-t data'}, 'Location', 'southoutside', 'Orientation', 'horizontal');
legend boxoff
exportgraphics(fig, fullfile(here, 'fig_prior.png'), 'Resolution', 150); close(fig);

%% 3. another prior of mu_h, mu_h ~ N(0, 1), in all three models: the adaptation
% p_new(y) = p(y) * E[p_new(mu_h)/p(mu_h) | y], from the draws of section 1
fprintf('\nmu_h ~ N(0, 1): log marginal likelihoods and their change\n');
lml_n = zeros(3, 2);
for d = 1:2
    for m = 1:3
        r = lnorm(post{m,d}(:,2), 0, 1) - lnorm(post{m,d}(:,2), pr.muh0, pr.Vmuh);
        lml_n(m,d) = lml(m,d) + logmeanexp(r);
    end
end
for m = 1:3
    fprintf('%-18s %10.2f (%+.2f) %10.2f (%+.2f)\n', mnames{m}, lml_n(m,1), lml_n(m,1) - lml(m,1), ...
        lml_n(m,2), lml_n(m,2) - lml(m,2));
end
fprintf('log Bayes factors, SV against constant variance: %.2f %.2f; SV-t against SV: %.2f %.2f\n', ...
    lml_n(2,:) - lml_n(1,:), lml_n(3,:) - lml_n(2,:));
fprintf('\nguide.m finished in %.1f minutes\n', toc(t_all)/60);

%% local functions
function [store_theta, hbar] = sv_gibbs(y, nsim, burnin, pr)
% the Gibbs sampler of guides/sv_gibbs, returning the parameter draws and the posterior mean
% of h
T = numel(y); offset = 1e-4;
mu0 = pr.mu0; Vmu = pr.Vmu; muh0 = pr.muh0; Vmuh = pr.Vmuh;
phi0 = pr.phi0; Vphi = pr.Vphi; nuh = pr.nuh; Sh = pr.Sh;
muh = log(var(y)); phi = .98; sig2h = .04;              % starting values
h = muh*ones(T,1);
store_theta = zeros(nsim, 4); hbar = zeros(T,1);
for isim = 1:burnin + nsim
    Kmu = 1/Vmu + sum(exp(-h));                         % K_mu = 1/V_mu + sum_t e^{-h_t}
    mu = (mu0/Vmu + exp(-h)'*y)/Kmu + randn/sqrt(Kmu);  % mu ~ N(c_mu/K_mu, 1/K_mu)

    ystar = log((y - mu).^2 + offset);  % s, then h: guides/sv_states
    h = ssm.ksc_ar1_mean(ystar, h, muh, phi, sig2h);

    hc = h - muh;                                          % h_t - mu_h
    u = [sqrt(1 - phi^2)*hc(1); hc(2:T) - phi*hc(1:T-1)];  % the state errors u_t
    sig2h = 1/gamrnd(nuh + T/2, 1/(Sh + u'*u/2));          % IG(nu_h + T/2, S_h + u'u/2)

    Kphi = 1/Vphi + hc(1:T-1)'*hc(1:T-1)/sig2h;             % K_phi and phihat of the proposal
    phihat = (phi0/Vphi + hc(1:T-1)'*hc(2:T)/sig2h)/Kphi;
    phic = 2;
    while abs(phic) >= 1, phic = phihat + randn/sqrt(Kphi); end
    g = @(x) .5*log(1 - x^2) - .5*(1 - x^2)*hc(1)^2/sig2h;  % log g(phi)
    if g(phic) - g(phi) > log(rand), phi = phic; end

    Kmuh = 1/Vmuh + (1 - phi^2 + (T-1)*(1 - phi)^2)/sig2h;  % mu_h given h, phi and sigma_h^2
    cmuh = muh0/Vmuh + ((1 - phi^2)*h(1) + (1 - phi)*sum(h(2:T) - phi*h(1:T-1)))/sig2h;
    muh = cmuh/Kmuh + randn/sqrt(Kmuh);

    if isim > burnin
        store_theta(isim - burnin, :) = [mu muh phi sig2h];
        hbar = hbar + h/nsim;
    end
end
end

function [store_theta, hbar] = svt_gibbs(y, nsim, burnin, pr)
% the Gibbs sampler of guides/sv_t, returning the parameter draws and the posterior mean of h
T = numel(y); offset = 1e-4;
mu0 = pr.mu0; Vmu = pr.Vmu; muh0 = pr.muh0; Vmuh = pr.Vmuh;
phi0 = pr.phi0; Vphi = pr.Vphi; nuh = pr.nuh; Sh = pr.Sh; nuub = pr.nuub;
muh = log(var(y)); phi = .98; sig2h = .04; nu = 5;     % starting values
h = muh*ones(T,1); lam = ones(T,1);
store_theta = zeros(nsim, 5); hbar = zeros(T,1);
for isim = 1:burnin + nsim
    w = 1./(lam.*exp(h));                           % 1/(lambda_t e^{h_t})
    Kmu = 1/Vmu + sum(w);                           % K_mu = 1/V_mu + sum_t 1/(lambda_t e^{h_t})
    mu = (mu0/Vmu + w'*y)/Kmu + randn/sqrt(Kmu);

    ystar = log((y - mu).^2./lam + offset);  % y*_t = log((y_t - mu)^2/lambda_t + c)
    h = ssm.ksc_ar1_mean(ystar, h, muh, phi, sig2h);

    e2 = (y - mu).^2.*exp(-h);  % lambda_t ~ IG((nu + 1)/2, (nu + e2_t)/2)
    lam = 1./gamrnd((nu + 1)/2, 2./(nu + e2));

    s1 = sum(log(lam)); s2 = sum(1./lam);  % nu: log p(lambda | nu), its mode and curvature
    fnu = @(x) T*(x/2*log(x/2) - gammaln(x/2)) - (x/2 + 1)*s1 - x/2*s2;
    gradK = @(x) deal(T/2*(log(x/2) + 1 - psi(x/2)) - (s1 + s2)/2, T/4*psi(1, x/2) - T/(2*x));
    [nuhat, Knu] = ssm.mode_newton(nu, gradK);
    nuc = nuhat + randn/sqrt(Knu);         % the proposal N(nuhat, 1/K_nu)
    if nuc > 2 && nuc < nuub && fnu(nuc) - fnu(nu) ...
            + .5*Knu*((nuc - nuhat)^2 - (nu - nuhat)^2) > log(rand)
        nu = nuc;
    end

    hc = h - muh;  % sigma_h^2, phi and mu_h: guides/sv_gibbs
    u = [sqrt(1 - phi^2)*hc(1); hc(2:T) - phi*hc(1:T-1)];
    sig2h = 1/gamrnd(nuh + T/2, 1/(Sh + u'*u/2));
    Kphi = 1/Vphi + hc(1:T-1)'*hc(1:T-1)/sig2h;
    phihat = (phi0/Vphi + hc(1:T-1)'*hc(2:T)/sig2h)/Kphi;
    phic = 2;
    while abs(phic) >= 1, phic = phihat + randn/sqrt(Kphi); end
    g = @(x) .5*log(1 - x^2) - .5*(1 - x^2)*hc(1)^2/sig2h;
    if g(phic) - g(phi) > log(rand), phi = phic; end
    Kmuh = 1/Vmuh + (1 - phi^2 + (T-1)*(1 - phi)^2)/sig2h;
    cmuh = muh0/Vmuh + ((1 - phi^2)*h(1) + (1 - phi)*sum(h(2:T) - phi*h(1:T-1)))/sig2h;
    muh = cmuh/Kmuh + randn/sqrt(Kmuh);

    if isim > burnin
        store_theta(isim - burnin, :) = [mu muh phi sig2h nu];
        hbar = hbar + h/nsim;
    end
end
end

function [lml, draws, lratio] = cv_posterior(y, pr, nsim)
% The constant variance, y_t ~ N(mu, e^{mu_h}): mu integrated out in closed form, then mu_h
% by the trapezoid rule on 2e4 points over 12 posterior standard deviations on either side of
% the mode. Returns log p(y), nsim exact draws of (mu, mu_h), and, as a check, the log of the
% ratio of the integral by adaptive quadrature on the same interval to the trapezoid one.
ngrid = 2e4;
T = numel(y); V = pr.Vmu; yc = y - pr.mu0;
a = yc'*yc; b = sum(yc);
% log p(y | mu_h) = log N(y; mu0*1, s*I + V*1*1'), s = e^{mu_h}
lpy = @(s) -T/2*log(2*pi) - .5*(T*log(s) + log(1 + V*T./s)) - (a - V*b^2./(s + V*T))./(2*s);
lf = @(m) lpy(exp(m)) - .5*log(2*pi*pr.Vmuh) - .5*(m - pr.muh0).^2/pr.Vmuh;
mhat = fminbnd(@(m) -lf(m), -20, 20, optimset('TolX', 1e-10));
sd = sqrt(2/T);                                        % about the posterior sd of mu_h
g = linspace(mhat - 12*sd, mhat + 12*sd, ngrid)';
f = lf(g); fmax = max(f);
lml = fmax + log(trapz(g, exp(f - fmax)));
lratio = log(integral(@(m) exp(lf(m) - fmax), g(1), g(end), 'AbsTol', 0, 'RelTol', 1e-12)) ...
    - log(trapz(g, exp(f - fmax)));
cdf = cumtrapz(g, exp(f - fmax)); cdf = cdf/cdf(end);
[cu, iu] = unique(cdf);
muh = interp1(cu, g(iu), rand(nsim, 1));               % mu_h by the inverse cdf
s = exp(muh);
Kmu = 1/V + T./s;                                      % mu given mu_h: K_mu = 1/V_mu + T/e^{mu_h}
mu = (pr.mu0/V + sum(y)./s)./Kmu + randn(nsim,1)./sqrt(Kmu);
draws = [mu muh];
end

function [lml, nse, lbm, ess] = is_logml(lp, draws, R)
% log p(y) by importance sampling, as in guides/tvp_compare: a t density with 5 degrees of
% freedom at the mean and covariance of the posterior draws, the cross-entropy fit of a normal
% density (Chan and Eisenstat, 2015), with heavier tails. lml is the log of the mean of all R
% weights; nse comes from 20 batches; lbm is the mean of the 20 batch estimates, the estimator
% of ml_sv.m; ess is the effective sample size of the weights, as a share of R.
nu = 5; d = size(draws, 2);
m = mean(draws, 1)'; C = chol(cov(draws), 'lower');
z = randn(d, R)./sqrt(chi2rnd(nu, 1, R)/nu);
phi = m + C*z;
lconst = gammaln((nu + d)/2) - gammaln(nu/2) - d/2*log(nu*pi) - sum(log(diag(C)));
logw = zeros(R, 1);
for r = 1:R  % log p(y, theta) - log g(phi)
    logw(r) = lp(phi(:,r)) - (lconst - (nu + d)/2*log(1 + z(:,r)'*z(:,r)/nu));
end
lml = logmeanexp(logw);
lb = zeros(20, 1); wb = reshape(logw, R/20, 20);
for b = 1:20
    lb(b) = logmeanexp(wb(:,b));
end
nse = std(lb)/sqrt(20);
lbm = mean(lb);
w = exp(logw - max(logw)); ess = sum(w)^2/sum(w.^2)/R;
end

function [lml, se] = prior_is(s2, muh, phi, sig2h, nu, N, nb)
% log p(y | theta) by importance sampling from the prior of h: nb batches of N paths, each
% weighted by the likelihood. nu = Inf gives normal errors, otherwise Student-t errors.
T = numel(s2); lb = zeros(nb, 1); lw_all = zeros(N, nb);
for b = 1:nb
    h = zeros(T, N);
    h(1,:) = muh + sqrt(sig2h/(1 - phi^2))*randn(1, N);
    for t = 2:T, h(t,:) = muh + phi*(h(t-1,:) - muh) + sqrt(sig2h)*randn(1, N); end
    if isinf(nu)
        lw = sum(-.5*log(2*pi) - .5*h - .5*s2.*exp(-h), 1);
    else
        lw = sum(gammaln((nu + 1)/2) - gammaln(nu/2) - .5*log(nu*pi) - .5*h ...
            - (nu + 1)/2*log(1 + s2.*exp(-h)/nu), 1);
    end
    lw_all(:,b) = lw'; lb(b) = logmeanexp(lw');
end
lml = logmeanexp(lw_all(:));
se = std(lb)/sqrt(nb);
end

function m = logmeanexp(x)
mx = max(x);
m = mx + log(mean(exp(x - mx)));
end
